<?php require __DIR__.'/bootstrap.php';$pageTitle='Guide du processus contractuel';$activeMenu='contrats';require __DIR__.'/../decaissement/includes/header.php';require __DIR__.'/../decaissement/includes/navbar.php';$steps=[['RH','Initialise le dossier, vérifie le fournisseur, choisit le chantier et les travaux, renseigne les effectifs et fait signer le DRH.'],['Technique','Définit l’objet, les travaux, la méthodologie, le planning, la date de début et le délai. Le Directeur technique valide.'],['Logistique','Valide véhicules, engins, matériaux, matériel et outillage. Le Directeur logistique signe.'],['QHSE','Définit les EPI, mesures de prévention, formations et habilitations. Le Responsable HSE/QHSE signe.'],['Comptabilité','Fixe acompte, retenue, pénalités et échéancier. Le Comptable/Responsable comptabilité ou le DG signe.'],['Direction générale','Examine le contrat consolidé. Le DG et le prestataire apposent les deux signatures externes qui activent le contrat.']];?>
<main class="mx-auto max-w-6xl px-4 py-8"><header class="rounded-3xl bg-black p-8 text-white"><p class="text-xs font-black uppercase tracking-[.25em] text-amber-300">Guide utilisateur</p><h1 class="mt-2 text-3xl font-black">Du brouillon au contrat actif</h1><p class="mt-3 max-w-3xl text-slate-300">Chaque service complète uniquement son volet. Une validation ouvre automatiquement l’étape suivante.</p></header><section class="mt-6 grid gap-4 md:grid-cols-2"><?php foreach($steps as $index=>$step):?><article class="rounded-3xl border bg-white p-6 shadow-sm"><div class="flex gap-4"><span class="flex h-11 w-11 shrink-0 items-center justify-center rounded-2xl bg-amber-400 text-lg font-black text-black"><?=$index+1?></span><div><h2 class="text-xl font-black"><?=$h($step[0])?></h2><p class="mt-2 leading-7 text-slate-600"><?=$h($step[1])?></p></div></div></article><?php endforeach;?></section><section class="mt-6 rounded-3xl border border-amber-200 bg-amber-50 p-6"><h2 class="text-xl font-black">À retenir</h2><ul class="mt-3 list-disc space-y-2 pl-5 text-slate-700"><li>Le montant contractuel est la somme des déboursés des lignes choisies.</li><li>La fin prévue est calculée automatiquement à partir du début et du délai.</li><li>Le PDF externe est disponible après les cinq validations internes.</li><li>Le contrat devient actif après les signatures du DG et du prestataire.</li><li>Les FEB contractuelles ne sont possibles que sur un contrat actif.</li></ul></section><a href="index.php" class="mt-6 inline-block rounded-xl bg-black px-5 py-3 font-black text-white">Retour aux contrats</a></main><?php require __DIR__.'/../decaissement/includes/footer.php';?>

